  /// < Screen mirroring is now playing media
  static const int SCMIRRORING_SINK_STATE_PLAYING = 4;

  /// < Screen mirroring is paused while playing media
  static const int SCMIRRORING_SINK_STATE_PAUSED = 5;

  /// < Screen mirroring is disconnected
  static const int SCMIRRORING_SINK_STATE_DISCONNECTED = 6;
  static const int SCMIRRORING_SINK_STATE_MAX = 7;
}

